#define EQ(x,e,m) do{int _r=(x);if(_r!=(e))fail(m,_r);}while(0)
int main(void){char p[]="/tmp/faisal-m111-sandbox-XXXXXX";struct fsb_service s;struct fsb_policy task={.capability_mask=FSB_CAP_EXEC|FSB_CAP_FILESYSTEM_READ,.filesystem_mask=FSB_CAP_FILESYSTEM_READ,.cpu_quota_ns=1000000,.memory_bytes=65536,.require_verification=1};struct fsb_policy cmd={.capability_mask=FSB_CAP_EXEC|FSB_CAP_COMMAND|FSB_CAP_FILESYSTEM_READ,.filesystem_mask=FSB_CAP_FILESYSTEM_READ,.cpu_quota_ns=2000000,.memory_bytes=65536,.require_verification=1};struct fsb_policy mem={.capability_mask=FSB_CAP_MEMORY_READ|FSB_CAP_MEMORY_WRITE,.filesystem_mask=0,.memory_bytes=1048576};struct fsb_policy browser={.capability_mask=FSB_CAP_BROWSER|FSB_CAP_NETWORK|FSB_CAP_FILESYSTEM_READ,.network_mask=1,.filesystem_mask=FSB_CAP_FILESYSTEM_READ,.memory_bytes=262144};struct fsb_policy deploy={.capability_mask=FSB_CAP_DEPLOY|FSB_CAP_FILESYSTEM_READ,.filesystem_mask=FSB_CAP_FILESYSTEM_READ,.require_verification=1};struct fsb_sandbox a,b,c,d,e;int fd=mkstemp(p);if(fd<0)fail("TMP",FSB_ERR_IO);close(fd);unlink(p);OK(fsb_open(&s,p),"OPEN");printf("M111_SANDBOX_FABRIC_OPEN_OK\n");OK(fsb_create(&s,FSB_TASK,10,0,1,"task-execution",&task,&a),"TASK");OK(fsb_create(&s,FSB_COMMAND,10,a.sandbox_id,1,"command-runner",&cmd,&b),"COMMAND");OK(fsb_create(&s,FSB_MEMORY,10,a.sandbox_id,1,"memory",&mem,&c),"MEMORY");OK(fsb_create(&s,FSB_BROWSER,10,a.sandbox_id,1,"browser",&browser,&d),"BROWSER");OK(fsb_create(&s,FSB_DEPLOY_CANARY,10,a.sandbox_id,1,"deploy-canary",&deploy,&e),"DEPLOY");printf("M111_SEPARATE_SANDBOX_CLASSES_OK classes=5\n");OK(fsb_admit(&a,FSB_CAP_EXEC,0,FSB_CAP_FILESYSTEM_READ,1),"TASK_ADMIT");EQ(fsb_admit(&a,FSB_CAP_COMMAND,0,0,0),FSB_ERR_POLICY,"TASK_COMMAND_DENY");EQ(fsb_admit(&c,FSB_CAP_COMMAND,0,0,0),FSB_ERR_POLICY,"MEMORY_COMMAND_DENY");EQ(fsb_admit(&d,FSB_CAP_BROWSER,2,0,0),FSB_ERR_POLICY,"BROWSER_NETWORK_DENY");OK(fsb_admit(&e,FSB_CAP_DEPLOY,0,FSB_CAP_FILESYSTEM_READ,1),"DEPLOY_VERIFIED_ADMIT");printf("M111_POLICY_CAPABILITY_NETWORK_FILESYSTEM_ISOLATION_OK\n");OK(fsb_start(&s,a.sandbox_id,&a),"START");OK(fsb_checkpoint(&s,a.sandbox_id,77,100,&a),"CHECKPOINT");if(!a.checkpoint_id)fail("CHECKPOINT_ID",FSB_ERR_STATE);printf("M111_CHECKPOINT_PROVENANCE_OK checkpoint=%llu\n",(unsigned long long)a.checkpoint_id);OK(fsb_start(&s,b.sandbox_id,&b),"COMMAND_START");OK(fsb_cancel(&s,b.sandbox_id,"obsolete",&b),"CANCEL");printf("M111_CANCELLATION_OK\n");OK(fsb_start(&s,c.sandbox_id,&c),"MEM_START");OK(fsb_fail(&s,c.sandbox_id,"worker-crash",&c),"FAIL");OK(fsb_recover(&s,c.sandbox_id,88,&c),"RECOVER");if(c.state!=FSB_RECOVERED||c.generation<3)fail("RECOVERY",FSB_ERR_STATE);printf("M111_CRASH_RECOVERY_OK generation=%llu\n",(unsigned long long)c.generation);OK(fsb_test_policy_matrix(&s),"POLICY_MATRIX");printf("M111_POLICY_MATRIX_OK\n");fsb_close(&s);OK(fsb_open(&s,p),"REPLAY");OK(fsb_query(&s,c.sandbox_id,&c),"REPLAY_QUERY");if(c.state!=FSB_RECOVERED)fail("REPLAY_STATE",FSB_ERR_CORRUPT);printf("M111_SANDBOX_REPLAY_OK\n");fsb_close(&s);fd=open(p,O_WRONLY|O_APPEND);if(fd<0||write(fd,"x",1)!=1)fail("CORRUPT_APPEND",FSB_ERR_IO);close(fd);EQ(fsb_open(&s,p),FSB_ERR_CORRUPT,"CORRUPTION");printf("M111_SANDBOX_REPLAY_FAIL_CLOSED_OK\n");unlink(p);printf("M111_SELFTEST_EXIT=0\n");return 0;}
